**Idea:** try $k = 1, 2, 3, \dots$ in order; the first $k$ not found in the array is the answer (it is at most $n+1$).

```c
#include <stdio.h>

int main(void)
{
    int n, i, k, found;
    int a[100];

    printf("Enter number of elements: ");
    scanf("%d", &n);
    printf("Enter %d integers: ", n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    for (k = 1; ; k++) {             /* candidate positive integer */
        found = 0;
        for (i = 0; i < n; i++) {
            if (a[i] == k) {
                found = 1;
                break;
            }
        }
        if (!found)
            break;                   /* k is missing */
    }
    printf("%d\n", k);
    return 0;
}
```

**Dry run** for `[3, 4, 10, 1]`: $k = 1$ is present, $k = 2$ is not, so output **2**. Negative numbers and 0 are never matched, so they are ignored automatically.

**Idea:** reshaping is legal only if the number of elements is unchanged: $m \times n = r \times c$. Element number $k$ in row-wise order ($k = 0 \dots mn-1$) sits at `a[k / n][k % n]` in the original and goes to `res[k / c][k % c]` in the new array.

```c
#include <stdio.h>

int main(void)
{
    int m, n, r, c, i, j, k;
    int a[10][10], res[100][100];

    printf("Enter rows and columns of the array: ");
    scanf("%d %d", &m, &n);
    printf("Enter the elements row wise:\n");
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++)
            scanf("%d", &a[i][j]);
    printf("Enter r and c of reshaped array: ");
    scanf("%d %d", &r, &c);

    if (m * n == r * c) {            /* reshape possible */
        for (k = 0; k < m * n; k++)
            res[k / c][k % c] = a[k / n][k % n];
        for (i = 0; i < r; i++) {
            for (j = 0; j < c; j++)
                printf("%d ", res[i][j]);
            printf("\n");
        }
    } else {                         /* not possible: print original */
        for (i = 0; i < m; i++) {
            for (j = 0; j < n; j++)
                printf("%d ", a[i][j]);
            printf("\n");
        }
    }
    return 0;
}
```

**Dry run**
- 2x3 array `1 2 3 / 4 5 6`, r = 1, c = 6: $6 = 6$, output `1 2 3 4 5 6`.
- Same array, r = 4, c = 3: $6 \ne 12$, so the original `1 2 3 / 4 5 6` is printed.

### Logic
- Define `struct student` with `rollNo`, `year`, `section` (1 to 3) and `cgpa` (float).
- `main` fills the record, reads the new section and CGPA, and calls `modify(&st, newSec, newCgpa)`.
- The structure is passed by **address**, so the function changes the original and `main` prints the updated values.

### Program
```c
#include <stdio.h>

struct student
{
    int rollNo;
    int year;
    int section;      /* 1 to 3 */
    float cgpa;
};

void modify(struct student *s, int newSection, float newCgpa)
{
    s->section = newSection;
    s->cgpa = newCgpa;
}

int main(void)
{
    struct student st;
    int sec;
    float cg;

    printf("Enter roll number, year of admission, section (1-3), CGPA: ");
    scanf("%d %d %d %f", &st.rollNo, &st.year, &st.section, &st.cgpa);

    printf("Enter new section (1-3) and new CGPA: ");
    scanf("%d %f", &sec, &cg);
    while (sec < 1 || sec > 3)
    {
        printf("Section must be 1, 2 or 3. Enter again: ");
        scanf("%d", &sec);
    }

    modify(&st, sec, cg);        /* call by reference */

    printf("\nUpdated record\n");
    printf("Roll number : %d\n", st.rollNo);
    printf("Year        : %d\n", st.year);
    printf("Section     : %d\n", st.section);
    printf("CGPA        : %.2f\n", st.cgpa);
    return 0;
}
```

### Sample run
```
Enter roll number, year of admission, section (1-3), CGPA: 101 2024 1 7.5
Enter new section (1-3) and new CGPA: 3 8.25

Updated record
Roll number : 101
Year        : 2024
Section     : 3
CGPA        : 8.25
```

