**Approach (no arrays):** read the numbers one at a time and only keep three counters (divisible by 2, 3, 4). A number outside [1, 1000] gives an error message and is read again. Finally
$$p_k = \frac{\text{count}_k}{n} \times 100\%$$
printed with 2 decimal places.

```c
#include <stdio.h>
int main()
{
    int n, i, x, c2 = 0, c3 = 0, c4 = 0;
    scanf("%d", &n);
    if (n < 1 || n > 1000) {
        printf("Error: n must be between 1 and 1000\n");
        return 0;
    }
    for (i = 1; i <= n; i++) {
        scanf("%d", &x);
        if (x < 1 || x > 1000) {
            printf("Error: %d is out of range [1...1000], enter again\n", x);
            i--;                         /* read this position again */
            continue;
        }
        if (x % 2 == 0) c2++;
        if (x % 3 == 0) c3++;
        if (x % 4 == 0) c4++;
    }
    printf("%.2f%%\n", c2 * 100.0 / n);
    printf("%.2f%%\n", c3 * 100.0 / n);
    printf("%.2f%%\n", c4 * 100.0 / n);
    return 0;
}
```

**Sample input:** n = 10, numbers 680 2 600 200 800 780 600 900 999 300 (with an invalid 1500 typed once).

**Output:**
```
Error: 1500 is out of range [1...1000], enter again
90.00%
60.00%
80.00%
```
Check: divisible by 2: 9 of 10 (all except 999), 90.00%; by 3: 600, 780, 600, 900, 999, 300 = 6, 60.00%; by 4: 680, 600, 200, 800, 780, 600, 900, 300 = 8, 80.00%. `100.0` forces floating-point division.

**Idea:** treat each row as a separate 1D array and bubble sort it in ascending order.

```c
#include <stdio.h>

int main(void)
{
    int a[4][4], i, j, k, temp;

    printf("Enter 16 elements of the 4x4 matrix:\n");
    for (i = 0; i < 4; i++)
        for (j = 0; j < 4; j++)
            scanf("%d", &a[i][j]);

    for (i = 0; i < 4; i++)                  /* each row */
        for (j = 0; j < 4 - 1; j++)          /* bubble sort passes */
            for (k = 0; k < 4 - 1 - j; k++)
                if (a[i][k] > a[i][k + 1]) {
                    temp = a[i][k];
                    a[i][k] = a[i][k + 1];
                    a[i][k + 1] = temp;
                }

    printf("Row wise sorted matrix:\n");
    for (i = 0; i < 4; i++) {
        for (j = 0; j < 4; j++)
            printf("%d ", a[i][j]);
        printf("\n");
    }
    return 0;
}
```

