{
    char ch;
    printf("Enter a character: ");
    scanf("%c", &ch);

    /* nested conditional (ternary) operator instead of if-else */
    ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z'))
        ? printf("%c is an alphabet\n", ch)
        : (ch >= '0' && ch <= '9')
            ? printf("%c is a digit\n", ch)
