### Logic
- Read `n`, allocate `n` ints with `malloc`, and read the elements.
- `findMax(arr, n, &index)` scans once, keeping the largest value and its position. A function can return only one value, so the **maximum is returned** and the **index is passed back through a pointer**.
- Free the memory at the end.

### Program
```c
#include <stdio.h>
#include <stdlib.h>

int findMax(int *arr, int n, int *index)
{
    int i, max = arr[0];
    *index = 0;
    for (i = 1; i < n; i++)
    {
        if (arr[i] > max)
        {
            max = arr[i];
            *index = i;
        }
    }
    return max;
}

int main(void)
{
    int n, i, max, idx;
    int *arr;

    printf("Input the number of elements to be stored in the array: ");
    scanf("%d", &n);
    if (n <= 0) return 1;

    arr = (int *)malloc(n * sizeof(int));
    if (arr == NULL)
    {
        printf("Memory not allocated\n");
        return 1;
    }

    printf("Input %d elements in the array :\n", n);
    for (i = 0; i < n; i++)
    {
        printf("element - %d : ", i);
        scanf("%d", &arr[i]);
    }

    max = findMax(arr, n, &idx);
    printf("%d, %d\n", max, idx);

    free(arr);
    return 0;
}
```

### Output for the test data (1 2 8 4 5)
```
8, 2
```
The largest element 8 is at index 2.

**Idea:** the last bit of an integer is 0 for even and 1 for odd numbers, so `a[i] & 1` gives exactly the required 0 or 1 without `%` or `==`.

```c
#include <stdio.h>

int main(void)
{
    int a[10] = {12, 7, 4, 15, 20, 33, 8, 1, 46, 9};
    int i;

    printf("Original array: ");
    for (i = 0; i < 10; i++)
        printf("%d ", a[i]);

    for (i = 0; i < 10; i++)
        a[i] = a[i] & 1;         /* even -> 0, odd -> 1 */

    printf("\nModified array: ");
    for (i = 0; i < 10; i++)
        printf("%d ", a[i]);
    printf("\n");
    return 0;
}
