### Steps
1. Open `StudentRecord.txt` in **write mode `"w"`** (creates the file), write one student's record with `fprintf`, close it.
2. Open it again in **append mode `"a"`**, so new data goes to the end, write two more records, close it.
3. Open it in **read mode `"r"`**, read records with `fscanf` until end of file, print them, close it.

Each record is written on one line as `name,rollno,marks` so that a name may contain spaces.

### Program
```c
#include <stdio.h>

struct student
{
    char name[51];      /* max size 50 */
    int rollno;
    float marks;
};

void readStudent(struct student *s)
{
    printf("Name: ");      scanf(" %50[^\n]", s->name);
    printf("Roll no: ");   scanf("%d", &s->rollno);
    printf("Marks: ");     scanf("%f", &s->marks);
}

int main(void)
{
    FILE *fp;
    struct student s;
    int i;

    /* 1. create the file and write one record */
    fp = fopen("StudentRecord.txt", "w");
    if (fp == NULL) { printf("Cannot create file\n"); return 1; }
    printf("Enter details of student 1\n");
    readStudent(&s);
    fprintf(fp, "%s,%d,%.2f\n", s.name, s.rollno, s.marks);
    fclose(fp);

    /* 2. reopen in append mode and add two records */
    fp = fopen("StudentRecord.txt", "a");
    if (fp == NULL) { printf("Cannot open file\n"); return 1; }
    for (i = 2; i <= 3; i++)
    {
        printf("Enter details of student %d\n", i);
        readStudent(&s);
        fprintf(fp, "%s,%d,%.2f\n", s.name, s.rollno, s.marks);
    }
    fclose(fp);

    /* 3. reopen in read mode and print all records */
    fp = fopen("StudentRecord.txt", "r");
    if (fp == NULL) { printf("Cannot open file\n"); return 1; }
    printf("\n%-25s %-8s %s\n", "Name", "Roll no", "Marks");
    while (fscanf(fp, " %50[^,],%d,%f", s.name, &s.rollno, &s.marks) == 3)
        printf("%-25s %-8d %.2f\n", s.name, s.rollno, s.marks);
    fclose(fp);

    return 0;
}
```

