**Logic**
1. Take the last digit `d = n % 10`.
2. Compute `d!` with an inner loop (0! = 1).
3. Add it to `sum`, remove the digit with `n = n / 10`, repeat while `n > 0`.

```c
#include <stdio.h>

int main(void)
{
    long n, t;
    int d, i;
    long fact, sum = 0;

    printf("Enter a number: ");
    scanf("%ld", &n);
    t = (n < 0) ? -n : n;

    do
    {
        d = t % 10;
        fact = 1;
        for (i = 2; i <= d; i++)      /* d! (0! = 1! = 1) */
            fact = fact * i;
        sum = sum + fact;
        t = t / 10;
    } while (t > 0);

    printf("Sum of factorials of digits = %ld\n", sum);
    return 0;
}
```

**Example:** for 145, $1! + 4! + 5! = 1 + 24 + 120 = 145$.
Output: `Sum of factorials of digits = 145`
(For 123: $1 + 2 + 6 = 9$.)

**Finding the rule:** 5 = 2(2) + 1, 12 = 2(5) + 2, 29 = 2(12) + 5, 70 = 2(29) + 12, 169 = 2(70) + 29. So
$$T_1 = 1,\quad T_2 = 2,\quad T_n = 2T_{n-1} + T_{n-2}\ \ (n \ge 3)$$

```c
#include <stdio.h>

int term(int n)
{
    if (n == 1) return 1;          /* base cases */
    if (n == 2) return 2;
    return 2 * term(n - 1) + term(n - 2);
}

int main()
{
    int i, n = 7;
    for (i = 1; i <= n; i++) {
        printf("%d", term(i));
        if (i < n) printf(",");
    }
    printf("\n");
    return 0;
}
```

