**Design:** `int Bitwise(int a, int b, char ch)` uses `switch` on the choice character and stores the result of `a & b` or `a | b`, which it returns to main.

```c
#include <stdio.h>

int Bitwise(int a, int b, char ch)
{
    int result = 0;
    switch (ch) {
        case '&': result = a & b; break;   /* bitwise AND */
        case '|': result = a | b; break;   /* bitwise OR  */
        default : printf("Invalid choice\n");
    }
    return result;
}

int main()
{
    int a, b;
    char ch;
    printf("Enter two integers: ");
    scanf("%d %d", &a, &b);
    printf("Enter choice (& or |): ");
    scanf(" %c", &ch);                     /* space skips the newline */
    printf("\n%d %c %d = %d\n", a, ch, b, Bitwise(a, b, ch));
    return 0;
}
```

