### Logic
1. Open `test.txt` in read mode and a temporary file `temp.txt` in write mode.
2. Read the input one line at a time. Scan each line with `strstr`: copy the text before every `"hello"` to the temp file, write `"bye"` in its place, skip the 5 characters of `"hello"`, and count the replacement.
3. Copy the rest of the line unchanged.
4. Close both files, delete `test.txt` and rename `temp.txt` to `test.txt`.
5. The function returns the total count, which `main` prints.

### Program
```c
#include <stdio.h>
#include <string.h>

int replaceWord(const char *file, const char *oldW, const char *newW)
{
    FILE *in, *out;
    char line[1024], *pos, *start;
    int count = 0, len = strlen(oldW);

    in = fopen(file, "r");
    if (in == NULL) return -1;
    out = fopen("temp.txt", "w");
    if (out == NULL) { fclose(in); return -1; }

    while (fgets(line, sizeof(line), in) != NULL)
    {
        start = line;
        while ((pos = strstr(start, oldW)) != NULL)
        {
            fwrite(start, 1, pos - start, out);   /* text before "hello" */
            fputs(newW, out);                     /* write "bye" */
            start = pos + len;                    /* skip "hello" */
            count++;
        }
        fputs(start, out);                        /* rest of the line */
    }

    fclose(in);
    fclose(out);
    remove(file);
    rename("temp.txt", file);
    return count;
}

int main(void)
{
    int n = replaceWord("test.txt", "hello", "bye");

    if (n < 0)
        printf("Could not open file\n");
    else
        printf("Total replacements: %d\n", n);
    return n < 0;
}
```

### Example
`test.txt` before:
```
hello world
say hello, hello again
```
After running, `test.txt` contains:
```
bye world
say bye, bye again
```
Screen output: `Total replacements: 3`

(Every occurrence of the character sequence `hello` is replaced. Lines are assumed shorter than 1024 characters.)

### Logic
- A record is a structure `struct student { char name[50]; int age; float height; };`
- The number of students `n` is read first, and an array of `n` records is created with `malloc`.
- Records are read and printed through a **structure pointer** `p`, using the arrow operator `p->member` and pointer increment `p++` to move to the next record.

### Program
```c
#include <stdio.h>
#include <stdlib.h>

struct student
{
    char name[50];
    int age;
    float height;      /* in cm */
};

int main(void)
{
    struct student *list, *p;
    int n, i;

    printf("Enter number of students in the class: ");
    scanf("%d", &n);
    if (n <= 0) return 1;

    list = (struct student *)malloc(n * sizeof(struct student));
    if (list == NULL) return 1;

    for (i = 0, p = list; i < n; i++, p++)
    {
        printf("Student %d - name, age, height: ", i + 1);
        scanf("%49s %d %f", p->name, &p->age, &p->height);
    }

    printf("\n%-20s %-5s %s\n", "Name", "Age", "Height");
    for (p = list; p < list + n; p++)          /* print using the pointer */
        printf("%-20s %-5d %.1f\n", p->name, p->age, p->height);

    free(list);
    return 0;
}
```

