Student 2 - name, age, height: Meera 19 160
Name                 Age   Height
Arjun                18    172.5
Meera                19    160.0
```
**Key point:** `p->age` is the same as `(*p).age`; `p++` advances by `sizeof(struct student)` bytes to the next record.

### 1. Structure
```c
struct library
{
    int  accNo;          /* accession number */
    char title[60];
    char author[40];
    float price;
    int  issued;         /* flag: 1 = issued, 0 = available */
};
```
An array `struct library book[MAX]` with a counter `count` stores the books.

### 2. Working of each menu option
1. **Add:** read all fields of a new book into `book[count]`, then `count++`.
2. **Display:** print every field of every book.
3. **Books of an author:** read an author name, print titles where `strcmp(book[i].author, name) == 0`.
4. **Title of a specified book:** read an accession number, search it and print its title.
5. **Count:** print `count`.
6. **Order of accession number:** copy the array, sort the copy by `accNo` with bubble sort, print it.
7. **Exit:** leave the `do-while` menu loop.

### 3. Program
```c
#include <stdio.h>
#include <string.h>

#define MAX 100

struct library
{
    int  accNo;
    char title[60];
    char author[40];
    float price;
    int  issued;          /* 1 = issued, 0 = available */
};

void printBook(struct library b)
{
    printf("%-6d %-25s %-18s %8.2f  %s\n", b.accNo, b.title, b.author,
           b.price, b.issued ? "Issued" : "Available");
}

int main(void)
{
    struct library book[MAX], sorted[MAX], t;
    int count = 0, choice, i, j, acc, found;
    char name[40];

    do
    {
        printf("\n--- LIBRARY MENU ---\n");
        printf("1. Add book information\n");
        printf("2. Display book information\n");
        printf("3. List all books of a given author\n");
        printf("4. List the title of specified book\n");
        printf("5. List the count of books in the library\n");
        printf("6. List the books in the order of accession number\n");
        printf("7. Exit\n");
        printf("Enter your choice: ");
        scanf("%d", &choice);

        switch (choice)
        {
        case 1:
            if (count == MAX) { printf("Library is full\n"); break; }
            printf("Accession number: ");  scanf("%d", &book[count].accNo);
            printf("Title: ");             scanf(" %59[^\n]", book[count].title);
            printf("Author: ");            scanf(" %39[^\n]", book[count].author);
            printf("Price: ");             scanf("%f", &book[count].price);
            printf("Issued? (1/0): ");     scanf("%d", &book[count].issued);
            count++;
            break;

        case 2:
            if (count == 0) { printf("No books\n"); break; }
            for (i = 0; i < count; i++)
                printBook(book[i]);
            break;

        case 3:
            printf("Author name: ");
            scanf(" %39[^\n]", name);
            found = 0;
            for (i = 0; i < count; i++)
                if (strcmp(book[i].author, name) == 0)
                {
                    printf("%s\n", book[i].title);
                    found = 1;
                }
            if (!found) printf("No book by this author\n");
            break;

        case 4:
            printf("Accession number: ");
            scanf("%d", &acc);
            found = 0;
            for (i = 0; i < count; i++)
                if (book[i].accNo == acc)
                {
                    printf("Title: %s\n", book[i].title);
                    found = 1;
                    break;
                }
            if (!found) printf("Book not found\n");
            break;

        case 5:
            printf("Number of books: %d\n", count);
            break;

        case 6:
            for (i = 0; i < count; i++)
                sorted[i] = book[i];
            for (i = 0; i < count - 1; i++)          /* bubble sort */
                for (j = 0; j < count - 1 - i; j++)
                    if (sorted[j].accNo > sorted[j + 1].accNo)
                    {
                        t = sorted[j];
                        sorted[j] = sorted[j + 1];
                        sorted[j + 1] = t;
                    }
            for (i = 0; i < count; i++)
                printBook(sorted[i]);
            break;

        case 7:
            printf("Exiting\n");
            break;

        default:
            printf("Invalid choice\n");
        }
    } while (choice != 7);

    return 0;
}
```

### 4. Sample interaction (abridged)
After adding books 205 "Let Us C" (Kanetkar), 101 "Programming in ANSI C" (Balagurusamy) and 150 "Test Your C Skills" (Kanetkar):
