**Steps**
1. Read first and last name.
2. Convert each to a binary string: vowel gives '1', consonant gives '0'.
3. Pad on the left with '0's to 16 bits.
4. Do bitwise AND, OR, XOR position by position on the two 16-bit strings.

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* name -> 16-bit string, vowel = '1', consonant = '0', left padded with '0' */
void toBinary(const char *name, char *bin)
{
    int len = strlen(name), pad = 16 - len, i;
    for (i = 0; i < pad; i++)
        bin[i] = '0';
    for (i = 0; i < len; i++)
        bin[pad + i] = strchr("aeiou", tolower(name[i])) ? '1' : '0';
    bin[16] = '\0';
}

int main(void)
{
    char first[17], last[17], b1[17], b2[17];
    char andR[17], orR[17], xorR[17];
    int i, x, y;

    printf("Enter first name: ");
    scanf("%16s", first);
    printf("Enter last name: ");
    scanf("%16s", last);

    toBinary(first, b1);
    toBinary(last, b2);

    for (i = 0; i < 16; i++) {
        x = b1[i] - '0';
        y = b2[i] - '0';
        andR[i] = (x & y) + '0';
        orR[i]  = (x | y) + '0';
        xorR[i] = (x ^ y) + '0';
    }
    andR[16] = orR[16] = xorR[16] = '\0';

    printf("First name : %s\n", b1);
    printf("Last name  : %s\n", b2);
    printf("AND        : %s\n", andR);
    printf("OR         : %s\n", orR);
    printf("XOR        : %s\n", xorR);
    return 0;
}
```

**Sample run** (first name "abc", last name "mno"):

```
First name : 0000000000000100
Last name  : 0000000000000001
AND        : 0000000000000000
OR         : 0000000000000101
XOR        : 0000000000000101
```

"abc" gives 100 and "mno" gives 001, as in the question; names are limited to 16 letters so they fit in 16 bits.

