### Logic
- `struct Student { char name[50]; int roll_no; float marks[5]; float avg; };`
- For each of the two students read name, roll number and 5 marks; average = sum / 5.
- Compare the two averages and print the name of the higher one (handle a tie).

### Program
```c
#include <stdio.h>

struct Student
{
    char name[50];
    int roll_no;
    float marks[5];
    float avg;
};

int main(void)
{
    struct Student s[2];
    int i, j;
    float sum;

    for (i = 0; i < 2; i++)
    {
        printf("Enter name and roll no of student %d: ", i + 1);
        scanf("%49s %d", s[i].name, &s[i].roll_no);
        printf("Enter marks of 5 subjects: ");
        sum = 0;
        for (j = 0; j < 5; j++)
        {
            scanf("%f", &s[i].marks[j]);
            sum += s[i].marks[j];
        }
        s[i].avg = sum / 5;
    }

    for (i = 0; i < 2; i++)
        printf("%s (Roll %d): average = %.2f\n", s[i].name, s[i].roll_no, s[i].avg);

    if (s[0].avg > s[1].avg)
        printf("Highest average: %s\n", s[0].name);
    else if (s[1].avg > s[0].avg)
        printf("Highest average: %s\n", s[1].name);
    else
        printf("Both students have the same average\n");

    return 0;
}
```

