**Method 1: using addition and subtraction**

```c
#include <stdio.h>

int main(void)
{
    int a, b;
    printf("Enter a and b: ");
    scanf("%d %d", &a, &b);
    printf("Before swap: a = %d, b = %d\n", a, b);

    a = a + b;      /* a holds the sum      */
    b = a - b;      /* b = old a            */
    a = a - b;      /* a = old b            */

