**Rules checked:** length 8 to 50; at least one lowercase, one uppercase, one digit, one special character; no 3 consecutive numeric values (like 567 or 765); no 3 same digits in a row (like 444); no 3 same alphabets in a row (like aaa).

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void)
{
    char p[100];
    int len, i, lower = 0, upper = 0, digit = 0, special = 0;

    printf("Enter password: ");
    scanf("%99s", p);
    len = strlen(p);

    if (len < 8 || len > 50) {
        printf("Not accepted (Error: length must be 8 to 50 characters)\n");
        return 0;
    }

    for (i = 0; i < len; i++) {
        if (islower(p[i]))      lower = 1;
        else if (isupper(p[i])) upper = 1;
        else if (isdigit(p[i])) digit = 1;
        else                    special = 1;
    }
    if (!lower || !upper || !digit || !special) {
        printf("Not accepted (Error: needs a lowercase, an uppercase, a number and a special character)\n");
        return 0;
    }

    for (i = 0; i + 2 < len; i++) {
        char a = p[i], b = p[i + 1], c = p[i + 2];
        if (isdigit(a) && isdigit(b) && isdigit(c)) {
            if (a == b && b == c) {
                printf("Not accepted (Error: 3 same numeric values consecutively)\n");
                return 0;
            }
            if ((b == a + 1 && c == b + 1) || (b == a - 1 && c == b - 1)) {
                printf("Not accepted (Error: contain 3 consecutive numeric values)\n");
                return 0;
            }
        }
        if (isalpha(a) && a == b && b == c) {
            printf("Not accepted (Error: 3 same alphabets consecutively)\n");
            return 0;
        }
    }

    printf("Accepted as a strong password.\n");
    return 0;
}
```

**Test data**

| Password | Output | Why |
|---|---|---|
| Ajay@123 | Not accepted (3 consecutive numeric values) | 1, 2, 3 increase by 1 |
| Ajay@111 | Not accepted (3 same numeric values) | 1, 1, 1 |
| Ajayyy@628 | Not accepted (3 same alphabets) | y, y, y |
| Ajay@781 | Accepted as a strong password | all rules pass |

Characters are compared by ASCII code, so `'5' + 1 == '6'` detects consecutive digits.

**Logic of Rec_ODD(M, P):**
- Base case: if M > P, stop.
- If M is odd, print it and jump to M + 2 (the next odd number).
- If M is even, move to M + 1 without printing.

```c
#include <stdio.h>

void Rec_ODD(int m, int p)
{
    if (m > p)                     /* base case */
        return;
    if (m % 2 != 0) {              /* odd */
        printf("%d,", m);
        Rec_ODD(m + 2, p);
    }
    else                           /* even: go to next number */
        Rec_ODD(m + 1, p);
}

int main()
{
    int m, p;
    printf("Enter M and P: ");
    scanf("%d %d", &m, &p);
    printf("\n");
    Rec_ODD(m, p);
    printf("\n");
    return 0;
}
```

**Sample runs:** input `1 10` gives
```
Enter M and P: 
1,3,5,7,9,
```
and input `2 10` gives `3,5,7,9,` (Rec_ODD(2,10) calls Rec_ODD(3,10), then prints 3, 5, 7, 9 and stops at Rec_ODD(11,10)).

