**Idea (only `==` allowed):** to know which of two numbers is larger, take their difference $d$ and test its sign bit: `(unsigned)d >> 31` is 0 for a positive $d$ and 1 for a negative $d$ (32-bit `int`). If votes tie ($d == 0$), use the difference of JEE marks instead (these are never equal).

```c
#include <stdio.h>

int main(void)
{
    int m1, m2, f1, f2, j1, j2, j3, j4, d;
    int SHIFT = sizeof(int) * 8 - 1;

    printf("Enter votes and JEE marks of M1 (m1 j1): ");
    scanf("%d %d", &m1, &j1);
    printf("Enter votes and JEE marks of M2 (m2 j2): ");
    scanf("%d %d", &m2, &j2);
    printf("Enter votes and JEE marks of F1 (f1 j3): ");
    scanf("%d %d", &f1, &j3);
    printf("Enter votes and JEE marks of F2 (f2 j4): ");
    scanf("%d %d", &f2, &j4);

    /* Male CR */
    d = m1 - m2;
    if (d == 0)                 /* tie in votes: compare JEE marks */
        d = j1 - j2;
    if ((((unsigned)d) >> SHIFT) == 0)   /* sign bit 0 => d positive */
        printf("M1 is male class representative (CR)\n");
    else
        printf("M2 is male class representative (CR)\n");

    /* Female CR */
    d = f1 - f2;
    if (d == 0)
        d = j3 - j4;
    if ((((unsigned)d) >> SHIFT) == 0)
        printf("F1 is female class representative (CR)\n");
    else
        printf("F2 is female class representative (CR)\n");

    return 0;
}
```

