int sumDigits(int n)
{
    if (n == 0)                         /* base case */
        return 0;
    return (n % 10) + sumDigits(n / 10); /* last digit + sum of the rest */
}

int main()
{
    int n;
    printf("Enter an integer: ");
    scanf("%d", &n);
    if (n < 0) n = -n;                  /* sign does not change the digits */
    printf("\nSum of digits = %d\n", sumDigits(n));
    return 0;
}
