    printf("Enter a number: ");
    scanf("%d", &n);

    if (n == 0)
        printf("Number is zero\n");
    else if (((unsigned)n >> (sizeof(int) * 8 - 1)) & 1)  /* sign bit */
        printf("%d is negative\n", n);
    else
        printf("%d is positive\n", n);
    return 0;
}
```

