**Logic:** a number n > 1 is prime if no integer i with $2 \le i \le \sqrt{n}$ divides it. Numbers less than 2 are not prime.

```c
#include <stdio.h>

int isPrime(int n)
{
    int i;
    if (n < 2)
        return 0;
    for (i = 2; i * i <= n; i++)
        if (n % i == 0)
            return 0;          /* divisor found: not prime */
    return 1;                  /* no divisor: prime */
}

int main()
{
    int n;
    printf("Enter an integer: ");
    scanf("%d", &n);
    if (isPrime(n))
        printf("\n%d is prime (function returned 1)\n", n);
    else
        printf("\n%d is not prime (function returned 0)\n", n);
    return 0;
}
```

