    }
}

int main(void)
{
    char d1, d2;
    printf("Enter two individual digits of hexa-decimal numbers\n");
    scanf(" %c", &d1);
    scanf(" %c", &d2);

    printf("Binary number\n");
    printBinary(d1);
    printf(" ");
    printBinary(d2);
    printf("\n");
    return 0;
}
